// npm i bcrypt
import bcrypt from 'bcrypt';

const ROUNDS = 12;
const DUMMY_HASH = await bcrypt.hash('not-a-real-password', ROUNDS);

export async function register(db, email, password) {
  if (password.length < 12) throw Object.assign(new Error('Password too short'), { status: 422 });
  const passwordHash = await bcrypt.hash(password, ROUNDS);   // salt is generated and embedded
  return db.users.insert({ email: email.toLowerCase(), passwordHash });
}

export async function login(db, email, password) {
  const user = await db.users.findByEmail(email.toLowerCase());
  // compare against a dummy hash when the user is missing, so timing does not leak
  const ok = await bcrypt.compare(password, user?.passwordHash ?? DUMMY_HASH);
  if (!user || !ok) throw Object.assign(new Error('Invalid credentials'), { status: 401 });
  return user;
}

