// npm i jsonwebtoken
import jwt from 'jsonwebtoken';

const SECRET = process.env.JWT_SECRET;       // at least 32 random bytes

export function issueToken(user) {
  return jwt.sign({ sub: user.id, role: user.role }, SECRET, { expiresIn: '15m', issuer: 'my-api' });
}

export function requireAuth(req, res, next) {
  const header = req.headers.authorization ?? '';
  const token = header.startsWith('Bearer ') ? header.slice(7) : null;
  if (!token) return res.status(401).json({ error: 'Missing token' });
  try {
    req.user = jwt.verify(token, SECRET, { algorithms: ['HS256'], issuer: 'my-api' });
    next();
  } catch (err) {
    const msg = err.name === 'TokenExpiredError' ? 'Token expired' : 'Invalid token';
    res.status(401).json({ error: msg });
  }
}

export const requireRole = (role) => (req, res, next) =>
  req.user?.role === role ? next() : res.status(403).json({ error: 'Forbidden' });

import crypto from 'node:crypto';

const enc = (obj) => Buffer.from(JSON.stringify(obj)).toString('base64url');

function sign(payload, secret, ttl = 3600) {
  const now = Math.floor(Date.now() / 1000);
  const data = `${enc({ alg: 'HS256', typ: 'JWT' })}.${enc({ ...payload, iat: now, exp: now + ttl })}`;
  const sig = crypto.createHmac('sha256', secret).update(data).digest('base64url');
  return `${data}.${sig}`;
}

function verify(token, secret) {
  const [h, p, s] = token.split('.');
  const expected = crypto.createHmac('sha256', secret).update(`${h}.${p}`).digest();
  const given = Buffer.from(s ?? '', 'base64url');
  if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) throw new Error('bad signature');
  const payload = JSON.parse(Buffer.from(p, 'base64url'));
  if (payload.exp < Date.now() / 1000) throw new Error('token expired');
  return payload;
}

const token = sign({ sub: 42, role: 'admin' }, 's3cret');
