// Simplified flow with plain fetch (use a library in production)
import crypto from 'node:crypto';

app.get('/auth/github', (req, res) => {
  const state = crypto.randomBytes(16).toString('hex');
  req.session.oauthState = state;
  const url = new URL('https://github.com/login/oauth/authorize');
  url.search = new URLSearchParams({
    client_id: process.env.GITHUB_ID,
    redirect_uri: 'https://myapp.com/auth/github/callback',
    scope: 'read:user user:email',
    state,
  });
  res.redirect(url);
});

app.get('/auth/github/callback', async (req, res) => {
  if (req.query.state !== req.session.oauthState) return res.status(400).send('Bad state');

  const tokenRes = await fetch('https://github.com/login/oauth/access_token', {
    method: 'POST',
    headers: { Accept: 'application/json', 'Content-Type': 'application/json' },
    body: JSON.stringify({
      client_id: process.env.GITHUB_ID,
      client_secret: process.env.GITHUB_SECRET,
      code: req.query.code,
    }),
  });
  const { access_token } = await tokenRes.json();

  const profile = await (await fetch('https://api.github.com/user', {
    headers: { Authorization: `Bearer ${access_token}` },
  })).json();

  req.session.userId = await findOrCreateUser('github', profile.id, profile.login);
  res.redirect('/');
});

