// a tiny token bucket (single process)
const buckets = new Map();
export function allow(key, capacity = 10, refillPerSec = 1) {
  const now = Date.now();
  const b = buckets.get(key) ?? { tokens: capacity, last: now };
  b.tokens = Math.min(capacity, b.tokens + ((now - b.last) / 1000) * refillPerSec);
  b.last = now;
  const ok = b.tokens >= 1;
  if (ok) b.tokens -= 1;
  buckets.set(key, b);
  return ok;
}

// npm i zod
import { z } from 'zod';

const createUser = z.object({
  name: z.string().trim().min(2).max(50),
  email: z.string().trim().toLowerCase().email(),
  age: z.coerce.number().int().min(13).max(120).optional(),
  role: z.enum(['user', 'editor']).default('user'),
});

export const validate = (schema, source = 'body') => (req, res, next) => {
  const result = schema.safeParse(req[source]);
  if (!result.success) {
    return res.status(422).json({
      error: 'Validation failed',
      fields: result.error.issues.map((i) => ({ path: i.path.join('.'), message: i.message })),
    });
  }
  req[source] = result.data;      // cleaned and typed
  next();
};

app.post('/users', validate(createUser), (req, res) => {
  res.status(201).json(req.body);     // { name, email, age?, role }
});

